+import test from "node:test";
+import assert from "node:assert/strict";
+import { allocate } from "../src/allocate.mjs";
+import { invoice } from "../src/caller.mjs";
+
+test("uses exact largest remainders and breaks equal remainders by input order", () => {
+  assert.deepEqual(allocate(10, [1, 1, 1]), [4, 3, 3]);
+  assert.deepEqual(allocate(2, [1, 1, 1]), [1, 1, 0]);
+  assert.deepEqual(allocate(7, [0, 1, 1]), [0, 4, 3]);
+});
+
+test("keeps exact results when sums and products exceed safe integer precision", () => {
+  const max = Number.MAX_SAFE_INTEGER;
+  assert.deepEqual(allocate(max, [max, max]), [4503599627370496, 4503599627370495]);
+  assert.deepEqual(allocate(max, [max, max - 1]), [4503599627370496, 4503599627370495]);
+});
+
+test("validates the full input contract and handles zero weights", () => {
+  for (const [total, weights] of [
+    [-1, [1]],
+    [1.5, [1]],
+    [Number.MAX_SAFE_INTEGER + 1, [1]],
+    [1, []],
+    [1, [1, , 2]],
+    [1, [-1]],
+    [1, [1.25]],
+    [1, [Number.MAX_SAFE_INTEGER + 1]],
+    [1, null],
+    [1, [0, 0]],
+  ]) {
+    assert.throws(() => allocate(total, weights), RangeError);
+  }
+  assert.deepEqual(allocate(0, [0, 0]), [0, 0]);
+  assert.deepEqual(allocate(0, [0, 3]), [0, 0]);
+});
+
+test("does not mutate weights and remains compatible with invoice", () => {
+  const weights = [2, 3, 5];
+  const before = weights.slice();
+  assert.deepEqual(allocate(11, weights), [2, 3, 6]);
+  assert.deepEqual(weights, before);
+
+  const lines = [{ sku: "a", weight: 1 }, { sku: "b", weight: 1 }];
+  assert.deepEqual(invoice(3, lines), [
+    { sku: "a", weight: 1, amount: 2 },
+    { sku: "b", weight: 1, amount: 1 },
+  ]);
+  assert.deepEqual(lines, [{ sku: "a", weight: 1 }, { sku: "b", weight: 1 }]);
+});
